(function(w){var a=w.BVC_PASSAGE_RESEARCH_CONTENT=w.BVC_PASSAGE_RESEARCH_CONTENT||[];[{"schema":"JBC_PASSAGE_READER_COMMENTARY_v1","researchId":"LUK_001_001_004_WORBS_READER_DRAFT_20261017","researchType":"WORBS","researchDepth":"CORE","sourcePath":"G:/내 드라이브/Jude_Lee_OS/01_PROJECTS/01_목회연구_WORBS_BICS/WORKING_COMMENTARY66_20261011/LUK_001_001_004_WORBS_READER_DRAFT_20261017.md","sourceSha256":"abb021eaf96000e299215c2ddad7e3ec3649afe9cfb1a9c324ba1f4ab859479e","passage":{"book":"luk","chapter":1,"v1":1,"v2":4,"ref":"누가복음 1:1–4"},"projectionStatus":"INTERNAL_READER_PROJECTION","professionalStatus":"CANDIDATE_REVIEW_ONLY","qualityStatus":"CANDIDATE_RESEARCH_REVIEW_REQUIRED","externalRelease":"NOT_AUTHORIZED","generatedByProject":"01_목회연구_WORBS_BICS","professionalAuthorityOwner":"01_목회연구_WORBS_BICS","title":"증언에서 확실한 이야기로","overview":["누가복음은 예수님의 탄생 장면보다 먼저 이 이야기를 어떻게 알게 되었으며 왜 기록하는지를 설명합니다. 이미 많은 사람이 사건을 서술하려 했고, 처음부터 목격하고 말씀을 섬긴 사람들이 그 사건들을 전해 주었습니다. 저자는 그 전승을 세심히 살펴 질서 있게 기록함으로써 데오빌로가 배운 복음의 확실성을 알도록 하려 합니다. 네 절은 하나의 긴 헬라어 문장으로 연결됩니다. 앞선 기록의 존재, 증언의 전달, 저자의 조사와 서술, 독자의 확신이라는 순서가 이 책의 문학적 출발점을 이룹니다."],"centralMessage":"누가복음은 예수님의 탄생 장면보다 먼저 이 이야기를 어떻게 알게 되었으며 왜 기록하는지를 설명합니다. 이미 많은 사람이 사건을 서술하려 했고, 처음부터 목격하고 말씀을 섬긴 사람들이 그 사건들을 전해 주었습니다. 저자는 그 전승을 세심히 살펴 질서 있게 기록함으로써 데오빌로가 배운 복음의 확실성을 알도록 하려 합니다. 네 절은 하나의 긴 헬라어 문장으로 연결됩니다. 앞선 기록의 존재, 증언의 전달, 저자의 조사와 서술, 독자의 확신이라는 순서가 이 책의 문학적 출발점을 이룹니다.","literaryStructure":[{"v1":1,"v2":1,"title":"먼저 존재했던 이야기들"},{"v1":2,"v2":2,"title":"목격과 말씀의 봉사가 만나는 자리"},{"v1":3,"v2":3,"title":"세심히 따라 살피고 질서 있게 쓰다"},{"v1":4,"v2":4,"title":"이미 배운 복음의 확실성을 알도록"}],"sections":[{"id":"luk1-1-1","v1":1,"v2":1,"title":"먼저 존재했던 이야기들","paragraphs":["누가는 자신의 책이 최초의 예수 이야기라고 주장하지 않습니다. ‘많은 사람’이 이미 서술을 시도했습니다. 헬라어 ἐπεχείρησαν(에페케이레산, ‘착수하였다’)은 반드시 실패한 시도를 뜻하지 않습니다. ἀνατάξασθαι διήγησιν은 사건을 정리해 하나의 이야기로 엮는 행위를 나타냅니다. 이 표현을 허구 창작의 증거로 읽을 이유는 없습니다. 사건을 어떻게 배열하고 전달할 것인지에 관한 저자의 의식이 드러납니다.","‘우리 가운데 이루어진 일들’을 수식하는 πεπληροφορημένων은 ‘이루어진·성취된’ 또는 ‘충분히 확증된’이라는 번역 가능성을 갖습니다. 누가복음 전체의 약속 성취 주제는 첫 이해에 무게를 주지만, 어휘 자체의 논의를 생략할 수는 없습니다. ‘우리 가운데’는 저자가 모든 사건을 직접 목격했다는 선언이 아니라 그 사건들이 증언 공동체의 현재와 관계된다는 표현입니다."]},{"id":"luk1-2-2","v1":2,"v2":2,"title":"목격과 말씀의 봉사가 만나는 자리","paragraphs":["사건의 서술은 증언의 전달에 의존합니다. αὐτόπται(아우톱타이)는 목격자들이며 ὑπηρέται τοῦ λόγου(휘페레타이 투 로구)는 말씀을 섬기는 사람들입니다. 두 표현은 본문에서 서로 단절된 집단이라기보다 처음부터 증언에 참여한 사람들의 연결된 자격을 밝힙니다. 그들은 사건을 보았고, 그 사건을 증언하는 말씀을 전달했습니다.","παρέδοσαν(파레도산, ‘전해 주었다’)은 전승의 전달 행위를 강조합니다. 누가는 직접 목격자와 자신 사이의 거리를 숨기지 않습니다. 다만 ‘전승’이라는 말만으로 개별 자료의 역사성이 자동 검증되었다고 단정하지도 않습니다. 다음 절의 세심한 조사가 그 간격을 메웁니다. 여기서 ‘말씀’을 후대에 완성된 신약 정경 전체와 곧바로 동일시하기보다 예수 그리스도에 관한 복음의 증언으로 이해하는 것이 문맥에 맞습니다."]},{"id":"luk1-3-3","v1":3,"v2":3,"title":"세심히 따라 살피고 질서 있게 쓰다","paragraphs":["이제 저자가 자기 결정을 말합니다. ἔδοξε κἀμοί(에도크세 카모이, ‘나도 쓰는 것이 좋겠다고 여겼다’)는 앞선 서술자들의 존재를 인정하면서 자신 역시 기록에 참여하겠다는 절제된 진술입니다. 저자는 특별한 환상이나 자신만의 비밀 지식을 내세우지 않습니다. 대신 파악하고 조사한 과정으로 집필의 근거를 설명합니다.","παρηκολουθηκότι(파레콜루데코티)는 사태를 면밀히 따라 살펴 온 상태를 나타내는 완료 분사입니다. ἄνωθεν(아노텐)은 문맥상 ‘처음부터’라는 뜻으로 읽는 것이 자연스럽지만, 다른 문맥에서는 ‘위로부터’라는 뜻도 지닙니다. 여기서 하늘에서 직접 모든 자료를 전달받았다는 주장을 읽어 내기보다는 사건의 시작부터 추적했다는 서술 의도를 읽어야 합니다. πᾶσιν ἀκριβῶς(파신 아크리보스)는 세밀한 살핌의 범위를 강조하지만 현대 역사학의 모든 질문을 무효화하는 무오성 공식은 아닙니다.","그가 선택한 기록 방식은 καθεξῆς(카덱세스), 곧 ‘차례대로·질서 있게’입니다. 이는 독자가 사건을 이해하도록 서사를 조직하겠다는 뜻입니다. 그러나 이 단어 하나로 누가복음의 모든 장면이 실제 발생 시각 순서대로만 배열되었다고 단정할 수 없습니다. 누가의 이야기에는 시간의 흐름뿐 아니라 예수님의 정체성과 사역을 드러내는 신학적 배열이 함께 작용합니다. 사도행전 11:4에서도 같은 단어는 사정을 차례로 설명하는 문맥에 나타납니다.","수신자는 κράτιστε Θεόφιλε(크라티스테 데오필레), ‘존귀한 데오빌로’입니다. 데오빌로라는 이름의 뜻이 ‘하나님을 사랑하는 사람’이라는 이유만으로 그를 상징적 가공 인물로 취급할 수 없습니다. κράτιστε는 격식을 갖춘 존칭이며 사도행전에서는 총독에게도 사용됩니다(행 23:26; 24:3; 26:25). 그러나 이 호칭만으로 데오빌로의 정확한 직위나 후원 관계를 확정할 수는 없습니다. 저자는 구체적 수신자를 향해 기록하되 그를 넘어 책을 읽을 사람들에게도 서술의 목적을 밝힙니다."]},{"id":"luk1-4-4","v1":4,"v2":4,"title":"이미 배운 복음의 확실성을 알도록","paragraphs":["긴 서문의 마지막은 ἵνα(히나, ‘…하도록’)로 시작하는 목적절입니다. 저자의 목표는 데오빌로가 이미 배운 말들의 ἀσφάλεια(아스팔레이아), 곧 견고함과 확실성을 알아보게 하는 것입니다. κατηχήθης(카테케데스)는 가르침을 받았다는 뜻의 수동형으로, 데오빌로가 이 책을 읽기 전부터 복음에 관한 교육을 받았음을 보여 줍니다. 그 교육의 장소와 교사가 누구였는지는 본문이 말하지 않습니다.","여기서 확실성은 의문이 전혀 없는 심리 상태가 아닙니다. 저자는 증언의 전달과 세밀한 조사, 질서 있는 서술을 통하여 배운 내용을 더 분명히 이해하도록 합니다. ἐπιγνῷς(에피그노스, ‘알게 되다·분명히 인식하다’)는 이 목적을 선명하게 합니다. 앞으로 펼쳐질 제사장 가정과 마리아의 이야기, 갈릴리 사역, 예루살렘으로 향하는 여정, 십자가와 부활은 단편적인 감동담이 아니라 데오빌로가 배운 복음의 근거를 차례로 드러내는 이야기입니다."]}],"lexicalCards":[],"discoveries":[],"canonicalLinks":[],"theologicalSynthesis":[],"alternativeReadings":[{"title":"문학적 서문의 기능","paragraphs":["1–4절은 하나의 격식 있는 헬라어 문장으로 이루어집니다. ‘많은 사람이 기록했으므로’라는 이유에서 출발하여 ‘목격자들이 전해 주었다’는 전승의 경로, ‘나도 세심히 살펴 기록한다’는 저자의 결정, ‘확실성을 알게 하려 한다’는 목적에 이릅니다. 이러한 구성은 누가복음이 우연히 모인 전승의 집합이 아니라 독자가 따라 읽을 수 있도록 조직된 복음의 서사임을 드러냅니다. 그렇다고 이 서문을 고대 역사서의 관례와 단순히 동일시하여 복음서의 신학적 성격을 지워서는 안 됩니다."]},{"title":"누가복음과 사도행전의 연결","paragraphs":["사도행전 1:1은 데오빌로에게 쓴 첫 글을 언급하며 예수님이 행하고 가르치기 시작하신 일을 회고합니다. 두 책은 연결되지만 각각의 서술 목적을 지닙니다. 누가복음은 예수님의 사역과 십자가·부활을 향하고, 사도행전은 그 사건의 증언이 성령 안에서 확장되는 과정을 전개합니다. 두 권을 함께 읽되 누가복음 자체의 서사적 흐름을 잃지 않아야 합니다."]},{"title":"저자와 자료에 관한 신중함","paragraphs":["이 서문은 저자의 이름, 직업, 특정 자료 목록을 직접 제시하지 않습니다. 누가라는 전통적 저자 명칭과 1:1–4 자체의 자기 설명을 구분해야 합니다. 또한 앞선 기록과 목격자의 전승을 언급한다는 사실만으로 마가복음 사용 여부나 다른 복음서와의 문서 관계를 확정할 수 없습니다. 저자가 주장한 것은 사건을 처음부터 면밀히 따라 살펴 질서 있게 썼다는 점입니다."]},{"title":"본문비평과 어휘 해석의 경계","paragraphs":["SBLGNT의 누가복음 1:1–4 읽기 본문을 대조했지만, 개별 사본의 이문과 비평 장치를 독립적으로 검증하지는 않았습니다. 따라서 ‘이문이 전혀 없다’는 주장은 하지 않습니다. 이 단락에서 검토한 핵심 쟁점은 πεπληροφορημένων의 의미 범위, ἄνωθεν의 문맥적 뜻, καθεξῆς의 서술 방식입니다. 이는 본문비평의 완결된 판정과 구별되는 문법·담화 해석입니다."]},{"title":"증언과 신뢰의 관계","paragraphs":["누가는 역사적 사건과 공동체의 증언, 저자의 서술을 대립시키지 않습니다. 사건은 목격자들의 전승으로 전달되고, 그 전승은 저자의 세밀한 살핌을 거쳐 독자에게 제시됩니다. 이 과정이 복음의 진실성을 기계적으로 증명한다는 뜻은 아니지만, 누가가 믿음을 근거 없는 감정이나 비밀 지식으로 제시하지 않는다는 점은 분명합니다. 확실성은 독자가 이미 배운 내용을 사건과 증언의 연결 속에서 다시 이해하는 데서 형성됩니다."]}],"relatedResearch":[],"readerSources":[{"name":"Tyndale Open Study Notes","locator":"Tyndale Open Study Notes, unfoldingWord Translation Notes, OSHB 및 히브리어 어휘 자료를 직접 사용하지 않았습니다","license":"CC BY-SA 4.0"},{"name":"unfoldingWord Translation Notes","edition":"v91","locator":"unfoldingWord Translation Notes, OSHB 및 히브리어 어휘 자료를 직접 사용하지 않았습니다","license":"CC BY-SA 4.0"}],"notes":["연구 참고자료\n* SBL Greek New Testament (SBLGNT) · Michael W. Holmes 편집, Society of Biblical Literature 및 Logos Bible Software · 2010년판, 누가복음 1:1–4 헬라어 읽기 본문 · 공식 사이트의 CC BY 4.0 안내, 추가 판본별 이용 조건 별도 확인 필요\n   * 저작권자 공식 명시: Copyright © 2010 Society of Biblical Literature and Logos Bible Software.\n   * 원자료: https://sblgnt.com 및 https://www.sbl-site.org/resources/digital-texts/sbl-greek-new-testament/\n   * 실제 대조 본문: https://www.biblegateway.com/passage/?search=Luke+1%3A1-4&version=SBLGNT\n   * 사용·변경 고지: 헬라어 읽기 본문의 어형과 문장 구조를 대조하고 한국어 문맥 해설을 새로 작성했습니다. 별도 형태소 분석·어휘·한국어 뜻풀이 데이터의 권리는 포함하지 않습니다.\n* Project01 누가복음 Book Profile · Jude Lee OS Project01 · BOOK_PROFILE_BUNDLE_NT01_GOSPELS_ACTS_v1.0_APPROVED 안의 BP-NT01-LUK, LUK_Luke_BOOK_PROFILE_Theological_Filter_v0.2 · 내부 승인 연구자료, 외부 이용허락 별도 확인 필요\n   * 원자료: Jude Lee OS Project01 내부 승인 Book Profile 번들.\n   * 사용·변경 고지: 누가복음의 구원 역사, 사도행전과의 연결 및 문학 구조를 해석적 배경으로 참고하되 서문 자체의 논증을 중심으로 새로 서술했습니다.","연구 및 재서술 안내\n이 글은 SBLGNT 누가복음 1:1–4의 헬라어 본문과 Project01 누가복음 Book Profile을 실제 대조·참고하여 작성한 한국어 WORBS 주석입니다. 공통 성경 원문과 개별 내부 연구자료의 출처를 구별했습니다. 개역한글판의 연속 번역문은 인용하지 않았으며 JudeBible Greek Original Language Dictionary, 생성된 Greek dict.js, Tyndale Open Study Notes, unfoldingWord Translation Notes, OSHB 및 히브리어 어휘 자료를 직접 사용하지 않았습니다. 본문과 참고 자료의 의미를 한국어로 새롭게 설명했지만 최종 원고의 독립·파생 저작물 여부를 검증 없이 확정하지 않습니다.","라이선스\nSBLGNT 공식 사이트의 CC BY 4.0 안내는 https://creativecommons.org/licenses/by/4.0/ 에서 확인할 수 있습니다. 실제 판본별 추가 고지 및 배포 형태에 대한 권리 검토는 별도로 필요합니다. Project01 내부 Book Profile의 권리는 SBLGNT와 별개이며, 이 원고 전체의 공개 라이선스는 별도 검증 전 확정하지 않습니다."],"sourceNotice":"연구 참고자료\n* SBL Greek New Testament (SBLGNT) · Michael W. Holmes 편집, Society of Biblical Literature 및 Logos Bible Software · 2010년판, 누가복음 1:1–4 헬라어 읽기 본문 · 공식 사이트의 CC BY 4.0 안내, 추가 판본별 이용 조건 별도 확인 필요\n   * 저작권자 공식 명시: Copyright © 2010 Society of Biblical Literature and Logos Bible Software.\n   * 원자료: https://sblgnt.com 및 https://www.sbl-site.org/resources/digital-texts/sbl-greek-new-testament/\n   * 실제 대조 본문: https://www.biblegateway.com/passage/?search=Luke+1%3A1-4&version=SBLGNT\n   * 사용·변경 고지: 헬라어 읽기 본문의 어형과 문장 구조를 대조하고 한국어 문맥 해설을 새로 작성했습니다. 별도 형태소 분석·어휘·한국어 뜻풀이 데이터의 권리는 포함하지 않습니다.\n* Project01 누가복음 Book Profile · Jude Lee OS Project01 · BOOK_PROFILE_BUNDLE_NT01_GOSPELS_ACTS_v1.0_APPROVED 안의 BP-NT01-LUK, LUK_Luke_BOOK_PROFILE_Theological_Filter_v0.2 · 내부 승인 연구자료, 외부 이용허락 별도 확인 필요\n   * 원자료: Jude Lee OS Project01 내부 승인 Book Profile 번들.\n   * 사용·변경 고지: 누가복음의 구원 역사, 사도행전과의 연결 및 문학 구조를 해석적 배경으로 참고하되 서문 자체의 논증을 중심으로 새로 서술했습니다.\n\n연구 및 재서술 안내\n이 글은 SBLGNT 누가복음 1:1–4의 헬라어 본문과 Project01 누가복음 Book Profile을 실제 대조·참고하여 작성한 한국어 WORBS 주석입니다. 공통 성경 원문과 개별 내부 연구자료의 출처를 구별했습니다. 개역한글판의 연속 번역문은 인용하지 않았으며 JudeBible Greek Original Language Dictionary, 생성된 Greek dict.js, Tyndale Open Study Notes, unfoldingWord Translation Notes, OSHB 및 히브리어 어휘 자료를 직접 사용하지 않았습니다. 본문과 참고 자료의 의미를 한국어로 새롭게 설명했지만 최종 원고의 독립·파생 저작물 여부를 검증 없이 확정하지 않습니다.\n\n라이선스\nSBLGNT 공식 사이트의 CC BY 4.0 안내는 https://creativecommons.org/licenses/by/4.0/ 에서 확인할 수 있습니다. 실제 판본별 추가 고지 및 배포 형태에 대한 권리 검토는 별도로 필요합니다. Project01 내부 Book Profile의 권리는 SBLGNT와 별개이며, 이 원고 전체의 공개 라이선스는 별도 검증 전 확정하지 않습니다."}].forEach(function(r){a.push(r);});if(w.JBCResearch&&w.JBCResearch._done)w.JBCResearch._done("luk");})(window);
